import { readFileSync } from "node:fs";
import { describe, expect, test } from "vitest";
import {
  bulkApprovalDetail,
  externalBulkTargets,
  hasExternalPending,
} from "../../../src/core/bulkApproval";

/**
 * 外部AIの提案をまとめて確かめて承認する（設計書6.87.18）。
 *
 * **束ねる側では何も迂回しない。** 1件ずつの反映の道へ流すので、
 * 作者のデータの保護（authorNotes・autoGenerated: false・authorLocked・
 * 6.18 の話数の扱い）はそのまま効く。ここで確かめるのは「どれを束ねるか」。
 */

const items = [
  { id: "a", name: "甲", status: "pending", origin: "external", source: "外部AIから：所属（理由：第3話）" },
  { id: "b", name: "乙", status: "pending", source: "性格" },
  { id: "c", name: "丙", status: "applied", origin: "external", source: "外部AIから：性格" },
  { id: "d", name: "丁", status: "failed", origin: "external", source: "外部AIから：外見" },
  { id: "e", name: "戊", status: "dismissed", origin: "external", source: "外部AIから：外見" },
  { id: "f", name: "己", status: "pending", origin: "plot", source: "プロットから：新規の人物" },
] as const;

describe("どれを束ねるか", () => {
  test("外部AIから来た、まだ判断していないもの（失敗して残っているものを含む）だけ", () => {
    expect(externalBulkTargets(items).map((item) => item.id)).toEqual(["a", "d"]);
  });

  test("外部AIの未判断が無ければ、ボタンを出さない", () => {
    expect(hasExternalPending(items)).toBe(true);
    expect(
      hasExternalPending(items.filter((item) => item.id !== "a" && item.id !== "d"))
    ).toBe(false);
  });
});

describe("確かめる画面の中身", () => {
  test("名前と中身を1件ずつ並べる", () => {
    const detail = bulkApprovalDetail(externalBulkTargets(items));
    expect(detail).toContain("甲");
    expect(detail).toContain("第3話");
    expect(detail).toContain("丁");
    expect(detail).not.toContain("乙");
  });

  test("多いときは切って、残りの件数を言う（黙って隠さない）", () => {
    const many = Array.from({ length: 30 }, (_, index) => ({
      id: String(index),
      name: `人物${index}`,
      status: "pending",
      origin: "external",
      source: "外部AIから：性格",
    }));
    const detail = bulkApprovalDetail(many);
    expect(detail).toContain("人物0");
    expect(detail).not.toContain("人物29");
    expect(detail).toContain("ほか10件");
  });
});

describe("提案パネルへのつなぎ", () => {
  const panel = readFileSync("src/features/proposalPanel.ts", "utf-8");
  const html = readFileSync("src/views/proposalPanelHtml.ts", "utf-8");

  test("画面に「外部AIの提案をまとめて確かめる」がある", () => {
    expect(html).toContain("approveExternal");
    expect(html).toContain("外部AIの提案をまとめて確かめる");
  });

  test("束ねても、1件ずつの反映の道（applyRecordUpdateById）を通す", () => {
    const start = panel.indexOf("private async approveExternalRecordUpdates");
    expect(start).toBeGreaterThan(0);
    const body = panel.slice(start, start + 4000);
    expect(body).toContain("externalBulkTargets");
    expect(body).toContain("applyRecordUpdateById");
    // 保存を直に呼ばない（保護を迂回する道を作らない）
    expect(body).not.toContain("saveOrUpdate");
  });
});
